import { ChangeDetectorRef, Component, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { forkJoin, finalize, switchMap } from 'rxjs';
import { ClaimsService } from '../../core/claims.service';
import { PeopleService } from '../../core/people.service';
import { PeriodsService } from '../../core/periods.service';
import { RatesService } from '../../core/rates.service';
import { SheetService } from '../../core/sheet.service';
import { People } from '../people/people';
import { Periods } from '../periods/periods';
import { Rates } from '../rates/rates';
import { SheetToday } from './sheet-today';

// Choose the active sheet by typing its id and loading it. The sheet is off the screen until it and
// everything kept under it (people, claims, rates, periods) have been re-read, so nothing is shown stale.
@Component({
  selector: 'app-sheet-picker',
  imports: [ReactiveFormsModule, SheetToday, Rates, Periods, People],
  template: `
    <form [formGroup]="form" (ngSubmit)="submit()" aria-label="Load sheet">
      <label for="sheet-id-input">Sheet id</label>
      <input id="sheet-id-input" data-testid="sheet-id-input" formControlName="id" />
      <button type="submit" data-testid="sheet-load">Load</button>
      @if (error()) {
        <p role="alert" data-testid="sheet-error">{{ error() }}</p>
      }
    </form>
    @if (loading()) {
      <p role="status">Loading sheet…</p>
    } @else if (sheets.sheetId(); as current) {
      <p>Sheet: <span data-testid="sheet-current-id">{{ current }}</span></p>
      <app-sheet-today />
      <app-rates />
      <app-periods />
      <app-people />
    }
  `,
})
export class SheetPicker {
  protected readonly sheets = inject(SheetService);
  protected readonly form = new FormGroup({ id: new FormControl('', { nonNullable: true }) });
  protected readonly error = signal('');
  protected readonly loading = signal(false);
  private readonly people = inject(PeopleService);
  private readonly claims = inject(ClaimsService);
  private readonly rates = inject(RatesService);
  private readonly periods = inject(PeriodsService);
  private readonly changes = inject(ChangeDetectorRef);

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
  }

  protected submit(): void {
    this.error.set('');
    const id = this.form.controls.id.value.trim();
    if (!/^[A-Za-z0-9_-]{1,100}$/.test(id)) {
      this.error.set('Enter a sheet id (letters, digits, - or _).');
      return;
    }
    this.loading.set(true);
    this.sheets
      .load(id)
      .pipe(
        switchMap(() => forkJoin([this.people.reload(), this.claims.reload(), this.rates.reload(), this.periods.reload()])),
        finalize(() => this.loading.set(false)),
      )
      .subscribe({ error: () => this.error.set('Could not load that sheet.') });
    // Take the sheet off the screen at once, so nothing shown before the load reads as re-read.
    this.changes.detectChanges();
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, of, tap } from 'rxjs';
import { SessionService } from './session.service';
import { SheetService } from './sheet.service';

export interface Period {
  id: number;
  /** Unique on the sheet. */
  name: string;
  /** The first date (yyyy-MM-dd) in the period. */
  from: string;
  /** The last date (yyyy-MM-dd) in the period. */
  to: string;
  /** Closed: its due-total is fixed and no claim dated in it can change. */
  closed: boolean;
  /** The due-total fixed when it closed (two decimals); null while open. */
  closedTotal: string | null;
}

export interface PeriodForm {
  name: string;
  from: string;
  to: string;
}

// The active sheet's periods, by from-date. No two overlap, so a date (and the claim dated on it)
// belongs to at most one.
@Injectable({ providedIn: 'root' })
export class PeriodsService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(SessionService);
  private readonly sheets = inject(SheetService);
  private readonly list = signal<Period[]>([]);

  readonly periods = this.list.asReadonly();

  /** The period whose dates contain the date (yyyy-MM-dd); undefined when none does. */
  periodOn(date: string): Period | undefined {
    return this.list().find((p) => p.from <= date && date <= p.to);
  }

  /** Re-read the active sheet's periods from the store. */
  reload(): Observable<unknown> {
    const id = this.sheets.sheetId();
    if (!id) {
      this.list.set([]);
      return of(null);
    }
    return this.http
      .get<Period[]>(this.url(id), { headers: this.session.headers() })
      .pipe(tap((periods) => {
        if (this.sheets.sheetId() === id) this.list.set(periods);
      }));
  }

  /** Add a period; refused when it ends before it starts, reuses a name or overlaps another. */
  add(form: PeriodForm): Observable<Period> {
    const id = this.sheets.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return this.http
      .post<Period>(this.url(id), form, { headers: this.session.headers() })
      .pipe(tap((p) => this.list.update((all) => [...all, p].sort((a, b) => a.from.localeCompare(b.from)))));
  }

  /** Close a period, fixing its due-total; refused when it is already closed. */
  close(periodId: number): Observable<Period> {
    const id = this.sheets.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return this.http
      .post<Period>(`${this.url(id)}/${periodId}/close`, null, { headers: this.session.headers() })
      .pipe(tap((p) => this.list.update((all) => all.map((q) => (q.id === p.id ? p : q)))));
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/periods`;
  }
}
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

